define(['mage/translate'],function($t){'use strict';return{statuses:{checkSubscription:['warning','error'],notFound:'not found'},subscriptionUrl:'https://amasty.com/amasty_recurring/customer/subscriptions',getActionLinkData:function(module){let actionLinkData={text:null,url:null}
if(module.upgrade_url){actionLinkData={text:$t('Upgrade Your Plan'),url:module.upgrade_url}}
if(this.isNeedCheckSubscription(module)){actionLinkData={text:$t('Check Your Subscriptions'),url:this.subscriptionUrl}}
if(this.isModuleNotFound(module)){actionLinkData={text:$t('Buy a License'),url:module.module_url}}
return actionLinkData;},isNeedCheckSubscription:function(module){return this.statuses.checkSubscription.includes(module.verify_status?.type);},isModuleNotFound:function(module){return module.verify_status?.status.toLowerCase()===this.statuses.notFound;}}});